156	    @ResponseBody
157	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
158	        HttpStatus status = HttpStatus.CONFLICT;
159	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
160	        return ResponseEntity.status(status).body(detail);
161	    }
