164	     * Handles {@link DuplicateHouseholdException} raised when an owner is created with a
165	     * last name and address that another owner already uses, without opting into a shared
166	     * household.
167	     *
168	     * @param e The {@link DuplicateHouseholdException} to be handled
169	     * @param request {@link HttpServletRequest} object referring to the current request.
170	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
171	     */
172	    @ExceptionHandler(DuplicateHouseholdException.class)
173	    @ResponseBody
174	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
175	        HttpStatus status = HttpStatus.CONFLICT;
176	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
177	        return ResponseEntity.status(status).body(detail);
178	    }
179	
180	    /**
181	     * Handles exception thrown by Bean Validation on controller methods parameters
182	     *
183	     * @param e The {@link MethodArgumentNotValidException} to be handled
184	     * @param request {@link HttpServletRequest} object referring to the current request.
185	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
186	     */
187	    @ExceptionHandler(MethodArgumentNotValidException.class)
188	    @ResponseBody
189	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
190	        HttpStatus status = HttpStatus.BAD_REQUEST;
191	        BindingErrorsResponse errors = new BindingErrorsResponse();
192	        BindingResult bindingResult = e.getBindingResult();
193	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
194	        if (bindingResult.hasErrors()) {
195	            errors.addAllErrors(bindingResult);
196	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
197	                .map(fieldError -> {
198	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
199	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
200	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
201	                        fieldError.getField(),
202	                        defaultMessage,
203	                        rejectedValue);
204	                    return new ValidationMessageDto(message)
205	                        .putAdditionalProperty("field", fieldError.getField())
206	                        .putAdditionalProperty("rejectedValue", rejectedValue)
207	                        .putAdditionalProperty("defaultMessage", defaultMessage);
208	                })
209	                .toList();
210	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
211	                .map(FieldError::getField)
212	                .distinct()
213	                .toList();
214	            logger.debug("Validation error at {} {}: {}",
215	                request.getMethod(),
216	                request.getRequestURI(),
217	                bindingResult.getFieldErrors());
218	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
219	            detail.setProperty("errors", invalidFields);
220	            return ResponseEntity.status(status).body(detail);
221	        }
222	        return ResponseEntity.status(status).body(detail);
223	    }
